<?php
require_once __DIR__ . '/../includes/functions.php';require_admin();$pageTitle='Управление проживанием — Лесная гавань';$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST') {verify_csrf();$action=$_POST['action']??'';
 if($action==='add'){$title=trim($_POST['title']??'');$type=trim($_POST['type']??'Домик');$description=trim($_POST['description']??'');$capacity=(int)($_POST['capacity']??0);$price=(float)($_POST['price_per_night']??0);$amenities=trim($_POST['amenities']??'');if($title===''||$description===''||$capacity<1||$price<=0)$errors[]='Заполните название, описание, вместимость и стоимость.';if(!$errors){$st=$pdo->prepare("INSERT INTO accommodations(title,type,description,capacity,price_per_night,amenities,status) VALUES(?,?,?,?,?,?,'active')");$st->execute([$title,$type,$description,$capacity,$price,$amenities]);set_flash('Вариант проживания добавлен.');redirect('/admin/accommodations.php');}}
 if($action==='toggle'){$id=(int)($_POST['id']??0);$st=$pdo->prepare("UPDATE accommodations SET status=IF(status='active','inactive','active') WHERE id=?");$st->execute([$id]);set_flash('Статус варианта обновлён.');redirect('/admin/accommodations.php');}
}
$items=$pdo->query('SELECT a.*,(SELECT COUNT(*) FROM bookings b WHERE b.accommodation_id=a.id) AS booking_count FROM accommodations a ORDER BY a.id DESC')->fetchAll();include __DIR__.'/../includes/header.php';
?>
<section class="container admin-page"><div class="admin-heading"><div><span class="eyebrow">КАТАЛОГ</span><h1>Варианты проживания</h1><p>Добавление новых предложений и управление доступностью.</p></div><a class="btn btn-outline-green" href="/admin/">← К статистике</a></div><div class="admin-form-card"><h2>Добавить вариант</h2><?php if($errors): ?><div class="alert alert-danger"><?php foreach($errors as $error): ?><div><?= e($error) ?></div><?php endforeach; ?></div><?php endif; ?><form method="post" class="row g-3"><?= csrf_field() ?><input type="hidden" name="action" value="add"><div class="col-md-6"><label class="form-label">Название</label><input class="form-control" name="title" required></div><div class="col-md-3"><label class="form-label">Тип</label><select class="form-select" name="type"><option>Домик</option><option>Коттедж</option><option>Номер</option><option>Глэмпинг</option></select></div><div class="col-md-3"><label class="form-label">Гостей</label><input class="form-control" type="number" name="capacity" min="1" max="20" required></div><div class="col-md-6"><label class="form-label">Стоимость за ночь, ₽</label><input class="form-control" type="number" name="price_per_night" min="1" step="1" required></div><div class="col-md-6"><label class="form-label">Удобства</label><input class="form-control" name="amenities" placeholder="Wi-Fi, кухня, терраса"></div><div class="col-12"><label class="form-label">Описание</label><textarea class="form-control" rows="2" name="description" required></textarea></div><div class="col-12"><button class="btn btn-green">Добавить в каталог</button></div></form></div><div class="admin-table-wrap"><h2>Список вариантов</h2><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Название</th><th>Тип</th><th>Гостей</th><th>Цена/ночь</th><th>Статус</th><th>Брони</th><th></th></tr></thead><tbody><?php foreach($items as $a): ?><tr><td><strong><?= e($a['title']) ?></strong></td><td><?= e($a['type']) ?></td><td><?= (int)$a['capacity'] ?></td><td><?= number_format((float)$a['price_per_night'],0,',',' ') ?> ₽</td><td><?= $a['status']==='active'?'Активен':'Скрыт' ?></td><td><?= (int)$a['booking_count'] ?></td><td><form method="post"><?= csrf_field() ?><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?= (int)$a['id'] ?>"><button class="table-action"><?= $a['status']==='active'?'Скрыть':'Опубликовать' ?></button></form></td></tr><?php endforeach; ?></tbody></table></div></div></section>
